mapper.update:
UPDATE users
SET display_name = #{displayName},
    bio = #{bio},
    icon_key = COALESCE(#{iconKey}, icon_key),
    updated_at = #{now}
WHERE id = #{id}

mapper.select:
SELECT * FROM ( SELECT u.id, u.username, u.display_name, u.bio, u.icon_key, u.created_at, , CASE WHEN LOWER(u.username) = LOWER(#{keyword}) THEN 0 -- ユーザー名が完全一致 WHEN u.username ILIKE #{pattern} || '%' THEN 1 -- ユーザー名が前方一致 ELSE 2 -- それ以外（途中に含む・表示名に含む） END AS match_rank FROM users u WHERE u.username ILIKE '%' || #{pattern} || '%' OR u.display_name ILIKE '%' || #{pattern} || '%' ) found
WHERE (found.match_rank, LOWER(found.username)) > (#{cursor.rank}, #{cursor.username})
ORDER BY found.match_rank, LOWER(found.username) LIMIT #{limit}
